-- Quillstone schema (Postgres). Generated from migrations.
create table accounts (
  id bigserial primary key,
  name text not null,
  plan text not null default 'free',
  billing_customer_id text unique
);

create table users (
  id bigserial primary key,
  account_id bigint not null references accounts(id),
  email text not null unique,
  role text not null check (role in ('owner', 'member'))
);

-- Invoices are generated by the billing system; users cannot edit them.
create table invoices (
  id bigserial primary key,
  account_id bigint not null references accounts(id),
  number text not null,
  issued_on date not null,
  total_cents bigint not null,
  status text not null check (status in ('open', 'paid', 'void'))
);

-- A private export is visible only to the user who created it; an 'account' export to everyone in the account.
create table exports (
  id bigserial primary key,
  account_id bigint not null references accounts(id),
  created_by bigint not null references users(id),
  visibility text not null default 'private' check (visibility in ('private', 'account')),
  title text not null,
  file_name text not null,
  size_bytes bigint not null,
  created_at timestamptz not null default now()
);
create index exports_account on exports (account_id, created_at);

create table billing_events (
  id text primary key,
  received_at timestamptz not null default now()
);
